#!/usr/bin/env node
/**
 * Normalise the election bundles into a SQLite database for D1.
 *
 * render/metadata/elections-test2 is 281 JSON documents totalling 322 MB, committed to
 * git and regenerated by `npm run build` -- which Cloudflare Pages runs at deploy time
 * in an environment that lacks the layer sources, so 223 of those elections are
 * rewritten with matchedCount 0 and loadable false on every single deploy. That is
 * what production serves. Static documents are the wrong container for this: the data
 * is relational (elections -> constituencies -> candidates -> counts), the client
 * downloads 1-3 MB to render one election, and the geography match is recomputed from
 * inputs that are not present rather than stored.
 *
 * The important table here is constituency_features. Today the constituency -> map
 * feature match is derived at build time from render/source-cache/, which is gitignored;
 * when the sources are absent the match silently becomes zero and stays zero. Stored as
 * rows, a missing match is a visible empty result and a one-time backfill, not a
 * permanent deploy-time regression.
 *
 * Every field that is not promoted to a column is preserved in a `meta` JSON column, so
 * this is lossless with respect to the source bundles. Two things are deliberately NOT
 * stored, because they are derivable and account for most of the bulk:
 *   - results[].elected      -- a duplicate of the elected subset of results[].candidates
 *   - results[].animationPayload -- derived from the count rows
 *
 * Usage:
 *   node scripts/build-elections-sqlite.mjs [--out <path>] [--limit N]
 */
import { readdirSync, readFileSync, existsSync, mkdirSync, rmSync, statSync, createWriteStream } from 'node:fs';
import { DatabaseSync } from 'node:sqlite';
import path from 'node:path';
import { createHash } from 'node:crypto';

const ROOT = process.cwd();
const SRC_DIR = path.join(ROOT, 'render/metadata/elections-test2');
const args = process.argv.slice(2);
const argVal = (name, fallback) => {
  const i = args.indexOf(name);
  return i >= 0 && args[i + 1] ? args[i + 1] : fallback;
};
const OUT = path.resolve(argVal('--out', 'tmp/elections.sqlite'));
const LIMIT = Number(argVal('--limit', Infinity));

export const SCHEMA = `
-- dataset.version is a hash of every source file this database was built from. The
-- elections API puts it in its edge cache key, so a reload invalidates cached responses
-- by itself instead of waiting a day or depending on someone bumping CACHE_VERSION.
CREATE TABLE dataset (
  key   TEXT PRIMARY KEY,
  value TEXT
);
CREATE TABLE elections (
  key                     TEXT PRIMARY KEY,
  body                    TEXT,
  body_slug               TEXT,
  body_group              TEXT,
  display_title           TEXT,
  contest_type            TEXT,
  kind                    TEXT,
  voting_system           TEXT,
  contest_status          TEXT,
  date                    TEXT,
  year                    INTEGER,
  source_map_id           TEXT,
  layer_id                TEXT,
  label_property          TEXT,
  candidate_rows_expected INTEGER,
  transfer_data_expected  INTEGER,
  meta                    TEXT
);

CREATE TABLE constituencies (
  election_key  TEXT NOT NULL,
  seq           INTEGER NOT NULL,
  name          TEXT,
  winner_party  TEXT,
  winner_name   TEXT,
  leading_party TEXT,
  leading_name  TEXT,
  leading_votes INTEGER,
  leading_pct   REAL,
  turnout_pct   REAL,
  majority      INTEGER,
  majority_pct  REAL,
  seats_won     INTEGER,
  seats_total   INTEGER,
  quota         INTEGER,
  electorate    INTEGER,
  source_file   TEXT,
  meta          TEXT,
  PRIMARY KEY (election_key, seq)
);

CREATE TABLE candidates (
  election_key     TEXT NOT NULL,
  constituency_seq INTEGER NOT NULL,
  candidate_id     TEXT,
  name             TEXT,
  party            TEXT,
  party_id         TEXT,
  person_id        TEXT,
  first_prefs      INTEGER,
  final_votes      REAL,
  elected          INTEGER,
  elected_at       INTEGER,
  excluded         INTEGER,
  excluded_at      INTEGER,
  status           TEXT,
  colour           TEXT,
  gender           TEXT,
  meta             TEXT
);

CREATE TABLE counts (
  election_key     TEXT NOT NULL,
  constituency_seq INTEGER NOT NULL,
  candidate_id     TEXT,
  count_number     INTEGER,
  total_votes      REAL,
  transfers        REAL,
  status           TEXT,
  row_id           INTEGER   -- countGroup row ordinal; preserved rather than re-derived
);

-- The count-animation payload, stored verbatim rather than reconstructed.
--
-- It was tempting to rebuild this from the counts and candidates tables, since its
-- countGroup is byte-identical to results[].countGroup. That does not work: the row
-- shape is not fixed. Five distinct shapes occur across the corpus -- the 1918 Dail
-- rows carry Auto_Returned_Ceann_Comhairle, Dail_Abbreviation, Official_Status and
-- Synthetic_Scraper_Row, which later elections do not -- and numbers are sometimes
-- strings ("15206") and sometimes numbers. Reconstruction reproduced only 19 of 4,702
-- constituencies exactly. Storing it verbatim costs 61.8 MB and is exact.
--
-- This does not undo the client win: the API serves one constituency per request, so
-- a payload is fetched only when that constituency is actually opened.
CREATE TABLE constituency_animation (
  election_key     TEXT NOT NULL,
  constituency_seq INTEGER NOT NULL,
  payload          TEXT,
  PRIMARY KEY (election_key, constituency_seq)
);

-- The stored geography match. See the header: this is the table that stops a missing
-- source cache from silently degrading production on every deploy.
CREATE TABLE constituency_features (
  election_key     TEXT NOT NULL,
  constituency_seq INTEGER NOT NULL,
  layer_id         TEXT,
  feature_id       TEXT,
  feature_name     TEXT,
  match_name       TEXT,
  matched          INTEGER,
  PRIMARY KEY (election_key, constituency_seq)
);

CREATE INDEX elections_body_date ON elections(body_slug, date);
CREATE INDEX elections_year      ON elections(year);
CREATE INDEX cons_election       ON constituencies(election_key);
CREATE INDEX cand_election_cons  ON candidates(election_key, constituency_seq);
CREATE INDEX cand_party          ON candidates(party);
CREATE INDEX cand_person         ON candidates(person_id);
CREATE INDEX counts_key          ON counts(election_key, constituency_seq, candidate_id);
CREATE INDEX confeat_layer       ON constituency_features(layer_id, feature_id);
`;

/**
 * Keep everything except the structures stored in their own tables.
 *
 * This deliberately does NOT exclude the promoted columns, and does NOT skip null or
 * empty-string values. The columns exist so the data can be queried in SQL; `meta` is
 * what reproduces the original object, and the endpoint spreads meta OVER the column
 * values so the originals always win.
 *
 * Every departure from that cost a round of debugging: SQLite has no boolean, so
 * elected/excluded came back as 1/0 instead of true/false; txt() turned a numeric
 * personId into "100052"; and skipping '' silently deleted dailAbbreviation,
 * officialCandidateId and officialStatus from every candidate. Storing verbatim and
 * querying via columns avoids the whole class.
 */
function residual(source, promoted, dropped = []) {
  const rest = {};
  for (const [k, v] of Object.entries(source)) {
    if (dropped.includes(k)) continue;
    if (v === undefined) continue;
    rest[k] = v;
  }
  return Object.keys(rest).length ? JSON.stringify(rest) : null;
}

// node:sqlite binds only null, number, string, bigint and Uint8Array -- undefined throws,
// and these bundles omit fields freely rather than setting them null.
const txt = (v) => {
  if (v === null || v === undefined) return null;
  if (typeof v === 'string') return v;
  if (typeof v === 'object') return JSON.stringify(v);
  return String(v);
};
const num = (v) => {
  if (v === null || v === undefined || v === '') return null;
  const n = Number(v);
  return Number.isFinite(n) ? n : null;
};
const bool = (v) => (v === null || v === undefined ? null : v ? 1 : 0);

if (!existsSync(SRC_DIR)) {
  console.error(`Source directory not found: ${path.relative(ROOT, SRC_DIR)}`);
  process.exit(1);
}
mkdirSync(path.dirname(OUT), { recursive: true });
rmSync(OUT, { force: true });

const db = new DatabaseSync(OUT);
db.exec('PRAGMA journal_mode = OFF; PRAGMA synchronous = OFF;');
db.exec(SCHEMA);

const insElection = db.prepare(`INSERT INTO elections VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`);
const insCons = db.prepare(`INSERT INTO constituencies VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`);
const insCand = db.prepare(`INSERT INTO candidates VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`);
const insCount = db.prepare(`INSERT INTO counts VALUES (?,?,?,?,?,?,?,?)`);
const insFeat = db.prepare(`INSERT OR REPLACE INTO constituency_features VALUES (?,?,?,?,?,?,?)`);
const insAnim = db.prepare(`INSERT OR REPLACE INTO constituency_animation VALUES (?,?,?)`);

const ELECTION_COLS = ['key', 'body', 'bodySlug', 'bodyGroup', 'displayTitle', 'contestType', 'kind',
  'votingSystem', 'contestStatus', 'date', 'year', 'sourceMapId', 'layerId', 'labelProperty',
  'candidateRowsExpected', 'transferDataExpected'];
const CONS_COLS = ['constituency', 'winnerParty', 'winnerName', 'leadingParty', 'leadingName',
  'leadingVotes', 'leadingPct', 'turnoutPct', 'majority', 'majorityPct', 'seatsWon', 'seatsTotal',
  'quota', 'electorate', 'sourceFile'];
const CAND_COLS = ['id', 'name', 'party', 'party_id', 'personId', 'firstPrefs', 'finalVotes',
  'elected', 'electedAt', 'excluded', 'excludedAt', 'status', 'colour', 'gender'];

let nElections = 0, nCons = 0, nCand = 0, nCounts = 0, nFeat = 0, nMatched = 0, nAnim = 0;
const files = readdirSync(SRC_DIR).filter((f) => f.endsWith('.json')).sort().slice(0, LIMIT);
let srcBytes = 0;
const datasetHash = createHash('sha256');

db.exec('BEGIN');
for (const file of files) {
  const full = path.join(SRC_DIR, file);
  srcBytes += statSync(full).size;
  const rawText = readFileSync(full, 'utf8');
  datasetHash.update(`${file}:${rawText.length}:`).update(rawText);
  const d = JSON.parse(rawText);
  const results = Array.isArray(d.results) ? d.results : [];

  insElection.run(
    txt(d.key), txt(d.body), txt(d.bodySlug), txt(d.bodyGroup), txt(d.displayTitle),
    txt(d.contestType), txt(d.kind), txt(d.votingSystem), txt(d.contestStatus), txt(d.date),
    num(d.year), txt(d.sourceMapId), txt(d.layerId), txt(d.labelProperty),
    bool(d.candidateRowsExpected), bool(d.transferDataExpected),
    // results is normalised into its own tables; the derived aggregates are recomputable.
    // entityIndex (85 KB) and mainLikeCandidateSummary (188 KB) are kept verbatim:
    // they are whole-election aggregates the client reads directly, and after the
    // animationPayload lesson -- reconstruction matched 19 of 4,702 -- deriving them
    // is not worth the risk. matchedCount/unmatchedCount/loadable/constituencies/
    // unmatchedConstituencies ARE dropped: those are one-line derivations over rows.
    // constituencies and unmatchedConstituencies are kept verbatim. The top-level
    // constituencies list is NOT a positional map of results[]: 1,324 of 4,706
    // positions disagree in the source, e.g. 1918 has an extra "Cork" entry that
    // shifts everything after it, and 2024 results[42].constituency is
    // "Wicklow Wexford3" where the list says "Wicklow Wexford". Deriving it produced
    // a plausible-looking list that was simply a different list.
    // matchedCount/unmatchedCount/loadable stay derived, so they follow the feature
    // table if the 851 unmatched constituencies are ever backfilled.
    residual(d, ELECTION_COLS, ['results', 'matchedCount', 'unmatchedCount', 'loadable'])
  );
  nElections += 1;

  results.forEach((r, seq) => {
    insCons.run(
      txt(d.key), seq, txt(r.constituency), txt(r.winnerParty), txt(r.winnerName),
      txt(r.leadingParty), txt(r.leadingName), num(r.leadingVotes), num(r.leadingPct),
      num(r.turnoutPct), num(r.majority), num(r.majorityPct), num(r.seatsWon),
      num(r.seatsTotal), num(r.quota), num(r.electorate), txt(r.sourceFile),
      // featureAliases and countNumbers are small and source-derived, so they ride
      // along in meta rather than being recomputed.
      // elected is kept verbatim: its order matches no rule tried. Sorting by
      // electedAt reproduced 861 of 2,375 multi-seat constituencies, candidate-array
      // order and first-preference order 619 each. It is dropped from lite responses,
      // so the client never carries it.
      residual(r, CONS_COLS, ['candidates', 'countGroup', 'animationPayload',
        'featureId', 'featureName', 'matchName', 'matched'])
    );
    nCons += 1;

    if (r.animationPayload) {
      insAnim.run(txt(d.key), seq, JSON.stringify(r.animationPayload));
      nAnim += 1;
    }

    if (r.featureId != null || r.matched != null) {
      insFeat.run(txt(d.key), seq, txt(d.layerId), txt(r.featureId), txt(r.featureName),
        txt(r.matchName), bool(r.matched));
      nFeat += 1;
      if (r.matched) nMatched += 1;
    }

    for (const c of r.candidates || []) {
      insCand.run(
        txt(d.key), seq, txt(c.id), txt(c.name), txt(c.party), txt(c.party_id),
        txt(c.personId), num(c.firstPrefs), num(c.finalVotes), bool(c.elected),
        num(c.electedAt), bool(c.excluded), num(c.excludedAt), txt(c.status),
        txt(c.colour), txt(c.gender),
        // counts is kept verbatim in meta. Deriving it from the counts table failed
        // twice: first on status '' being stored as NULL, then on the count at which a
        // candidate was elected, where candidate.counts carries the CANDIDATE's status
        // ("Deemed elected") while the countGroup row it supposedly comes from has ''.
        // Same lesson as animationPayload -- these structures are not reconstructions.
        residual(c, CAND_COLS, [])
      );
      nCand += 1;
    }

    for (const row of r.countGroup || []) {
      insCount.run(txt(d.key), seq, txt(row.Candidate_Id ?? row.id), num(row.Count_Number),
        num(row.Total_Votes), num(row.Transfers), txt(row.Status) || null, num(row.id));
      nCounts += 1;
    }
  });
}
{
  const insDataset = db.prepare('INSERT INTO dataset VALUES (?, ?)');
  insDataset.run('version', datasetHash.digest('hex').slice(0, 16));
  insDataset.run('builtAt', new Date().toISOString());
  insDataset.run('sourceFiles', String(files.length));
}
db.exec('COMMIT');
db.exec('VACUUM');
db.close();

// Primary keys, used to target the chunked UPDATEs that carry oversized meta values.
const KEY_COLS = {
  elections: ['key'],
  constituencies: ['election_key', 'seq'],
  constituency_features: ['election_key', 'constituency_seq'],
  constituency_animation: ['election_key', 'constituency_seq'],
};

// D1 imports SQL, not SQLite files, so emit a dump alongside the database.
// `wrangler d1 execute <name> --remote --file=<this>` is then the whole load step.
// NOT `d1 import`: that subcommand does not exist in wrangler 4.x, and the command this
// comment used to name printed the help text and exited 0-ish, which reads as success.
let sqlBytes = 0;
if (!args.includes('--no-sql')) {
  const sqlPath = OUT.replace(/\.sqlite$/, '') + '.sql';
  const dump = new DatabaseSync(OUT, { readOnly: true });
  const lit = (v) => {
    if (v === null || v === undefined) return 'NULL';
    if (typeof v === 'number') return Number.isFinite(v) ? String(v) : 'NULL';
    return `'${String(v).replace(/'/g, "''")}'`;
  };
  const out = createWriteStream(sqlPath);
  const write = (s) => new Promise((res) => { out.write(s) ? res() : out.once('drain', res); });
  await write('PRAGMA defer_foreign_keys = true;\n');
  // Idempotent: reloading D1 after a schema change would otherwise collide with the
  // existing tables, and `d1 execute` has no --replace.
  for (const t of ['elections', 'constituencies', 'candidates', 'counts',
    'constituency_features', 'constituency_animation', 'dataset']) {
    await write(`DROP TABLE IF EXISTS ${t};\n`);
  }
  await write(SCHEMA.replace(/^\s*--.*$/gm, '').replace(/\n{2,}/g, '\n'));
  for (const table of ['elections', 'constituencies', 'candidates', 'counts', 'constituency_features', 'constituency_animation', 'dataset']) {
    const cols = dump.prepare(`SELECT name FROM pragma_table_info('${table}')`).all().map((r) => r.name);
    const rows = dump.prepare(`SELECT * FROM ${table}`).all();
    // Batched multi-row INSERTs, capped by BYTES rather than row count. D1 rejects an
    // oversized statement with SQLITE_TOOBIG, and row count is a poor proxy for size
    // here: a candidates row carrying a large `meta` JSON blob can be orders of
    // magnitude bigger than a counts row, so a fixed 200-row batch blew the limit on
    // some tables and not others.
    const MAX_STATEMENT_BYTES = 40_000;
    const prefix = `INSERT INTO ${table} (${cols.join(',')}) VALUES `;
    let batch = [];
    let batchBytes = 0;
    const flush = async () => {
      if (!batch.length) return;
      await write(`${prefix}${batch.join(',')};\n`);
      batch = [];
      batchBytes = 0;
    };
    // A row can exceed the cap on its own -- the 1996 NI Forum region-wide contest
    // carries a 112 KB `forum` blob in meta -- and no batching helps, because the
    // statement is one tuple. Such rows are written with meta NULL and the value is
    // then appended in chunks. Splitting the raw string before escaping is safe:
    // concatenating the pieces reproduces the original exactly.
    const oversized = [];
    for (const r of rows) {
      let tuple = `(${cols.map((c) => lit(r[c])).join(',')})`;
      if (tuple.length + prefix.length > MAX_STATEMENT_BYTES && KEY_COLS[table]) {
        // Null out whichever string column is longest and append it afterwards. Doing
        // this by longest-column rather than by a hardcoded name means a new wide
        // column does not silently reintroduce SQLITE_TOOBIG.
        const wide = cols
          .filter((c) => typeof r[c] === 'string')
          .sort((a, b) => r[b].length - r[a].length)[0];
        if (wide) {
          oversized.push({ row: r, col: wide });
          tuple = `(${cols.map((c) => (c === wide ? 'NULL' : lit(r[c]))).join(',')})`;
        }
      }
      if (batchBytes && batchBytes + tuple.length + prefix.length > MAX_STATEMENT_BYTES) await flush();
      batch.push(tuple);
      batchBytes += tuple.length + 1;
    }
    await flush();

    const CHUNK = 20_000;
    let chunkedRows = 0;
    for (const { row: r, col } of oversized) {
      const where = KEY_COLS[table].map((c) => `${c} = ${lit(r[c])}`).join(' AND ');
      for (let i = 0; i < r[col].length; i += CHUNK) {
        const piece = lit(r[col].slice(i, i + CHUNK));
        await write(`UPDATE ${table} SET ${col} = COALESCE(${col},'') || ${piece} WHERE ${where};\n`);
      }
      chunkedRows += 1;
    }
    if (chunkedRows) console.log(`  ${table}: ${chunkedRows} oversized value(s) written in chunks`);
  }
  dump.close();
  await new Promise((res) => out.end(res));
  sqlBytes = statSync(sqlPath).size;
}

const outBytes = statSync(OUT).size;
const mb = (b) => (b / 1048576).toFixed(1);
console.log(`Elections -> SQLite`);
console.log(`  elections            ${nElections}`);
console.log(`  constituencies       ${nCons}`);
console.log(`  candidates           ${nCand}`);
console.log(`  count rows           ${nCounts}`);
console.log(`  animation payloads   ${nAnim}`);
console.log(`  feature matches      ${nFeat}  (${nMatched} matched, ${nFeat - nMatched} unmatched)`);
console.log(`  source JSON          ${mb(srcBytes)} MB`);
console.log(`  sqlite               ${mb(outBytes)} MB   (${(100 * outBytes / srcBytes).toFixed(1)}% of source)`);
if (sqlBytes) console.log(`  sql dump (for D1)    ${mb(sqlBytes)} MB`);
console.log(`  -> ${path.relative(ROOT, OUT)}`);
